#!/usr/bin/env python3
# Autonomously generated by an AI agent.
"""Build or install Mixxx's bpm-improvements branch in user directories."""

import argparse
import os
from pathlib import Path
import shlex
import shutil
import subprocess
import sys
import tempfile

REPOSITORY = "https://github.com/gabba43/mixxx.git"
REF = "bpm-improvements"
SOURCE_FILES = (
    "CMakeLists.txt",
    "src/main.cpp",
    "src/analyzer/plugins/beatgridevidence.cpp",
    "src/track/beatgridmode.h",
)
INSTALL_LAYOUT = {
    "CMAKE_INSTALL_BINDIR": "bin",
    "CMAKE_INSTALL_DATADIR": "share",
    "CMAKE_INSTALL_DATAROOTDIR": "share",
    "CMAKE_INSTALL_LIBDIR": "lib",
    "CMAKE_INSTALL_DOCDIR": "share/doc/mixxx",
}


class SourceUpdateError(ValueError):
    pass


def run(command, **kwargs):
    command = [str(arg) for arg in command]
    print("+ " + shlex.join(command), flush=True)
    return subprocess.run(command, check=True, **kwargs)


def absolute(value):
    path = Path(value).expanduser().absolute()
    if any(char in str(path) for char in "\r\n\x00"):
        raise ValueError("Paths must not contain newlines or NUL bytes")
    return path


def is_source(path):
    return all((path / name).is_file() for name in SOURCE_FILES)


def source_directory(explicit, destination, repository, ref):
    script = Path(__file__).resolve()
    candidates = (script.parent, script.parents[1], Path.cwd())
    source = (
        absolute(explicit)
        if explicit
        else next(
            (candidate for candidate in candidates if is_source(candidate)),
            destination,
        )
    )
    if source.exists():
        if not is_source(source):
            raise ValueError(
                f"Not a Mixxx bpm-improvements source directory: {source}"
            )
        print(f"Found existing sources: {source}", flush=True)
    else:
        source.parent.mkdir(parents=True, exist_ok=True)
        run(
            [
                "git",
                "clone",
                "--single-branch",
                "--branch",
                ref,
                "--",
                repository,
                source,
            ]
        )
        if not is_source(source):
            raise ValueError(
                "The selected Git ref does not include the native BPM "
                f"improvements: {ref}"
            )
    return source


def git_value(source, *arguments):
    return subprocess.check_output(
        ["git", "-C", str(source), *arguments],
        text=True,
        stderr=subprocess.PIPE,
    ).strip()


def prepare_sources(source, managed_directory, repository, ref, update=None):
    if not (source / ".git").exists():
        if update:
            raise SourceUpdateError(
                "Source archives cannot be updated with Git"
            )
        print(f"Source: {source} (archive, no Git revision)", flush=True)
        return
    managed = source.resolve() == managed_directory.resolve()
    should_update = update if update is not None else managed
    try:
        branch = git_value(source, "branch", "--show-current")
        if should_update and not branch:
            tag = subprocess.run(
                [
                    "git",
                    "-C",
                    str(source),
                    "rev-parse",
                    "--verify",
                    f"refs/tags/{ref}^{{commit}}",
                ],
                capture_output=True,
                text=True,
            )
            pinned = tag.returncode == 0 and tag.stdout.strip() == git_value(
                source, "rev-parse", "HEAD"
            )
            if update is not True and pinned:
                should_update = False
                print(f"Using pinned tag: {ref}", flush=True)
            else:
                raise SourceUpdateError(
                    "Cannot update a detached checkout. Select a branch, "
                    "or use --no-update to build this revision explicitly."
                )
        if should_update:
            if git_value(
                source, "status", "--porcelain", "--untracked-files=no"
            ):
                raise SourceUpdateError(
                    f"Local changes in {source}; commit/stash them first, "
                    "or use --no-update to build the local changes."
                )
            if managed:
                origin = git_value(source, "remote", "get-url", "origin")
                if branch != ref or origin.rstrip("/") != repository.rstrip(
                    "/"
                ):
                    raise SourceUpdateError(
                        f"Managed checkout is {origin}, branch {branch}; "
                        f"expected {repository}, branch {ref}. "
                        "Use --no-update to keep that checkout explicitly."
                    )
            upstream = git_value(
                source,
                "rev-parse",
                "--abbrev-ref",
                "--symbolic-full-name",
                "@{upstream}",
            )
            if managed and upstream != f"origin/{branch}":
                raise SourceUpdateError(
                    f"Unexpected managed upstream: {upstream}"
                )
            print(
                f"Updating sources by fast-forward from {upstream}", flush=True
            )
            run(["git", "-C", source, "pull", "--ff-only", "--no-rebase"])
        revision = git_value(source, "rev-parse", "HEAD")
        dirty = bool(
            git_value(source, "status", "--porcelain", "--untracked-files=no")
        )
    except subprocess.CalledProcessError as error:
        raise SourceUpdateError(
            f"Git source check/update failed in {source}. "
            "No build was started. Resolve the Git error, or choose "
            "--no-update explicitly to use the existing source revision."
        ) from error
    print(
        f"Source directory: {source}\n"
        f"Source branch: {branch or '(detached)'}\n"
        f"Source commit: {revision}" + (" (local changes)" if dirty else ""),
        flush=True,
    )
    if not should_update:
        print(
            "Sources were not updated (--update requests a fast-forward).",
            flush=True,
        )


def dependency_help():
    distribution = "unknown distribution"
    release = Path("/etc/os-release")
    if release.is_file():
        for line in release.read_text().splitlines():
            if line.startswith("PRETTY_NAME="):
                distribution = line.split("=", 1)[1].strip('"')
    print(
        f"Detected: {distribution}\n"
        "Requires C++20, CMake >= 3.22, pkg-config, Make or Ninja,\n"
        "Python 3.8+ for this installer, and Mixxx's native libraries:\n"
        "Qt 6 with private headers, audio/codecs, USB/MIDI, etc.\n"
        "Debian/Ubuntu: see packaging/debian/control.in for native packages.\n"
        "Fedora: dnf builddep mixxx; Arch: the Mixxx PKGBUILD makedepends;\n"
        "openSUSE: zypper source-install --build-deps-only mixxx.\n"
        "Distro packages can target an older Qt/version: also check\n"
        "LINUX_INSTALL.md and CMake errors for missing dependencies.\n"
        "This installer executes no system package manager or sudo command.\n"
        "Guide: https://github.com/mixxxdj/mixxx/wiki/Compiling-On-Linux\n"
        "Analysis uses the native Queen Mary and SoundTouch backends.\n"
        "No inference runtime, model download, pip or virtualenv is needed."
    )


def configure_build(source, build, prefix, extra):
    validate_cache_source(build, source)
    build.mkdir(parents=True, exist_ok=True)
    command = ["cmake", "-S", source, "-B", build]
    if not (build / "CMakeCache.txt").exists():
        command += [
            "-DCMAKE_BUILD_TYPE=Release",
            "-DBUILD_TESTING=OFF",
            "-DBUILD_BENCH=OFF",
        ]
        if shutil.which("ninja"):
            command += ["-G", "Ninja"]
    command += extra
    command += [f"-DCMAKE_INSTALL_PREFIX={prefix}"]
    command += [f"-D{key}={value}" for key, value in INSTALL_LAYOUT.items()]
    command += ["-DINSTALL_USER_UDEV_RULES=OFF"]
    run(command)


def cache_values(build):
    cache = build / "CMakeCache.txt"
    values = {}
    if cache.is_file():
        for line in cache.read_text(encoding="utf-8").splitlines():
            if line and not line.startswith(("#", "//")) and "=" in line:
                key, _, value = line.partition("=")
                values[key.partition(":")[0]] = value
    return values


def validate_cache_source(build, source):
    if (build / "CMakeCache.txt").exists():
        cached = cache_values(build).get("CMAKE_HOME_DIRECTORY")
        if not cached or Path(cached).resolve() != source.resolve():
            raise ValueError(
                f"Build cache in {build} belongs to different sources; "
                "select a separate --build-dir"
            )


def validate_install_layout(build, prefix):
    cached = cache_values(build)
    if (
        any(cached.get(key) != value for key, value in INSTALL_LAYOUT.items())
        or cached.get("CMAKE_INSTALL_PREFIX") != str(prefix)
        or cached.get("INSTALL_USER_UDEV_RULES") != "OFF"
    ):
        raise ValueError(
            "Cached install layout does not match this local installation; "
            "rerun without --skip-build to configure relative install paths"
        )


def existing_build(build, source):
    cache = build / "CMakeCache.txt"
    executable = build / "mixxx"
    if (
        cache.is_file()
        and executable.is_file()
        and os.access(executable, os.X_OK)
    ):
        for line in cache.read_text(encoding="utf-8").splitlines():
            if line.startswith("CMAKE_HOME_DIRECTORY:INTERNAL="):
                if Path(line.partition("=")[2]).resolve() == source.resolve():
                    return
                break
    raise ValueError(
        f"--skip-build requires a completed build of {source} in {build}; "
        "rerun without --skip-build to compile"
    )


def write_atomic(path, content, mode=0o600):
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        mode="w", encoding="utf-8", dir=path.parent, delete=False
    ) as stream:
        temporary = Path(stream.name)
        try:
            stream.write(content)
            stream.close()
            temporary.chmod(mode)
            temporary.replace(path)
        finally:
            temporary.unlink(missing_ok=True)


def desktop_quote(value):
    value = (
        str(value)
        .replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("`", "\\`")
        .replace("$", "\\$")
    )
    return '"' + value.replace("\\", "\\\\").replace("%", "%%") + '"'


def check_launchers(prefix, bin_dir, data_home):
    launcher = prefix / "bin/mixxx-bpm-improvements"
    link = bin_dir / "mixxx-bpm-improvements"
    desktop = (
        data_home / "applications/org.mixxx.Mixxx.BpmImprovements.desktop"
    )
    if link != launcher and (link.exists() or link.is_symlink()):
        if not link.is_symlink() or link.resolve() != launcher.resolve():
            raise ValueError(
                f"Refusing to replace an unrelated starter: {link}"
            )
    for path in (launcher, desktop):
        if path.is_symlink() or (
            path.exists() and (
                not path.is_file()
                or "# Mixxx bpm-improvements starter"
                not in path.read_text(encoding="utf-8")
            )
        ):
            raise ValueError(
                f"Refusing to replace an unrelated starter: {path}"
            )


def install_launchers(prefix, profile, bin_dir, data_home):
    check_launchers(prefix, bin_dir, data_home)
    launcher = prefix / "bin/mixxx-bpm-improvements"
    command = [
        prefix / "bin/mixxx",
        "--resource-path",
        prefix / "share/mixxx",
        "--settings-path",
        profile,
    ]
    write_atomic(
        launcher,
        "#!/bin/sh\n# Autonomously generated by an AI agent.\n"
        "# Mixxx bpm-improvements starter\nexec "
        + shlex.join([str(arg) for arg in command])
        + ' "$@"\n'
        + "# End of autonomously generated text.\n",
        0o755,
    )
    bin_dir.mkdir(parents=True, exist_ok=True)
    link = bin_dir / "mixxx-bpm-improvements"
    if link.resolve() != launcher.resolve():
        if link.exists() or link.is_symlink():
            raise ValueError(
                f"Refusing to replace an unrelated starter: {link}"
            )
        else:
            link.symlink_to(launcher)
    icon = str(prefix / "share/icons/hicolor/scalable/apps/mixxx.svg").replace(
        "\\", "\\\\"
    )
    write_atomic(
        data_home / "applications/org.mixxx.Mixxx.BpmImprovements.desktop",
        "# Autonomously generated by an AI agent.\n"
        "# Mixxx bpm-improvements starter\n"
        "[Desktop Entry]\nType=Application\nName=Mixxx (BPM Improvements)\n"
        "Comment=Mixxx with native BPM improvements\n"
        f"Exec={desktop_quote(launcher)} %F\nIcon={icon}\n"
        "Terminal=false\nCategories=AudioVideo;Audio;\n"
        "# End of autonomously generated text.\n",
        0o644,
    )
    return link


def choose_mode(mode):
    if mode:
        return mode
    if not sys.stdin.isatty():
        raise ValueError(
            "Select --mode build or --mode install for non-interactive use"
        )
    while True:
        answer = (
            input(
                "Nur kompilieren (Terminal/eigener Shortcut) [b] oder "
                "mit Starter im Benutzerverzeichnis installieren [i]? "
            )
            .strip()
            .lower()
        )
        if answer in {"b", "build"}:
            return "build"
        if answer in {"i", "install"}:
            return "install"


def memory_limits():
    values = {}
    try:
        for line in Path("/proc/meminfo").read_text().splitlines():
            key, value = line.split(":", 1)
            values[key] = int(value.split()[0]) * 1024
    except (OSError, ValueError):
        pass
    total = values.get("MemTotal", 2 * 1024**3)
    available = values.get("MemAvailable", total)
    try:
        cgroup = next(
            line.split(":", 2)[2]
            for line in Path("/proc/self/cgroup").read_text().splitlines()
            if line.startswith("0::")
        )
        root = Path("/sys/fs/cgroup")
        current = (root / cgroup.lstrip("/")).resolve()
        directories = [root]
        while root in current.parents:
            directories.append(current)
            current = current.parent
        for directory in directories:
            try:
                limit = (directory / "memory.max").read_text().strip()
                if limit != "max":
                    used = int((directory / "memory.current").read_text())
                    total = min(total, int(limit))
                    available = min(available, max(0, int(limit) - used))
            except (OSError, ValueError):
                continue
    except (OSError, ValueError, StopIteration):
        pass
    return total, available


def compile_budget(percent, jobs):
    if percent is None and sys.stdin.isatty():
        while True:
            answer = (
                input("RAM-Budget zum Kompilieren: 25%, 50% oder 75% [50%]: ")
                .strip()
                .rstrip("%")
                or "50"
            )
            if answer in {"25", "50", "75"}:
                percent = int(answer)
                break
    percent = percent or 50
    total, available = memory_limits()
    budget = max(1, min(total * percent // 100, available * 4 // 5))
    parallel = max(1, budget // (1536 * 1024**2))
    parallel = min(parallel, jobs or os.cpu_count() or 1, os.cpu_count() or 1)
    print(
        f"Compile RAM budget: {percent}% requested, "
        f"{budget / 1024 ** 3:.2f} GiB available for the build; "
        f"{parallel} parallel jobs (estimate: 1.5 GiB per job).",
        flush=True,
    )
    return budget, parallel


def build_command(build, budget, jobs):
    command = ["cmake", "--build", build, "--parallel", jobs]
    if shutil.which("systemd-run"):
        prefix = [
            "systemd-run",
            "--user",
            "--scope",
            "--quiet",
            f"--property=MemoryMax={budget}",
            "--property=MemorySwapMax=0",
            "--",
        ]
        try:
            probe = subprocess.run(
                prefix + ["true"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=10,
            )
            supported = probe.returncode == 0
        except (OSError, subprocess.TimeoutExpired):
            supported = False
        if supported:
            print("Enforcing compile RAM budget with a user systemd scope.")
            return prefix + command
    print(
        "No user memory-control scope available: RAM budget controls job "
        "parallelism only; it is not a hard memory limit.",
        flush=True,
    )
    return command


def main(argv=None):
    home = Path.home()
    data_home = absolute(
        os.environ.get("XDG_DATA_HOME", home / ".local/share")
    )
    cache_home = absolute(os.environ.get("XDG_CACHE_HOME", home / ".cache"))
    config_home = absolute(os.environ.get("XDG_CONFIG_HOME", home / ".config"))
    parser = argparse.ArgumentParser(
        description=__doc__,
        epilog="Close this Mixxx profile before installing/updating. "
        "No sudo or system package installation.",
    )
    parser.add_argument(
        "--mode",
        choices=("build", "install"),
        help="Compile, or install with a starter; asked when omitted",
    )
    parser.add_argument(
        "--prefix",
        type=absolute,
        default=home / ".local/opt/mixxx-bpm-improvements",
    )
    parser.add_argument(
        "--source-dir",
        help="Existing sources, or a new directory to clone into",
    )
    parser.add_argument(
        "--build-dir",
        type=absolute,
        default=cache_home / "mixxx-bpm-improvements/build",
    )
    parser.add_argument(
        "--skip-build",
        action="store_true",
        help="Reuse a completed build; only finish the local installation",
    )
    parser.add_argument(
        "--profile",
        type=absolute,
        default=config_home / "mixxx-bpm-improvements",
    )
    parser.add_argument(
        "--bin-dir", type=absolute, default=home / ".local/bin"
    )
    parser.add_argument(
        "--jobs",
        type=int,
        help="Maximum parallel compile jobs within the RAM budget",
    )
    parser.add_argument(
        "--ram-percent",
        type=int,
        choices=(25, 50, 75),
        help="Compile RAM budget; asked interactively, otherwise 50 percent",
    )
    parser.add_argument("--repository", default=REPOSITORY)
    updates = parser.add_mutually_exclusive_group()
    updates.add_argument(
        "--update",
        dest="update",
        action="store_true",
        help="Fast-forward an existing checkout from its configured upstream",
    )
    updates.add_argument(
        "--no-update",
        dest="update",
        action="store_false",
        help="Build existing sources without fetching updates",
    )
    parser.set_defaults(update=None)
    parser.add_argument(
        "--ref",
        default=REF,
        help="Branch/tag for clones and managed checkout updates",
    )
    parser.add_argument(
        "--cmake-arg",
        action="append",
        default=[],
        help="Extra CMake argument; use --cmake-arg=-DNAME=VALUE",
    )
    parser.add_argument(
        "--print-deps",
        action="store_true",
        help="Show native prerequisites and exit",
    )
    args = parser.parse_args(argv)
    if args.print_deps:
        dependency_help()
        return
    if args.skip_build and args.update:
        parser.error("--update cannot be combined with --skip-build")
    print(f"Installer: {Path(__file__).resolve()}", flush=True)
    mode = choose_mode(args.mode)
    if sys.platform != "linux" or os.geteuid() == 0:
        parser.error("Run this installer as a regular user on Linux")
    if args.jobs is not None and args.jobs < 1:
        parser.error("--jobs must be at least 1")
    budget, jobs = (
        (0, 0)
        if args.skip_build
        else compile_budget(args.ram_percent, args.jobs)
    )
    build_tools = (
        ("cmake", "pkg-config")
        if not args.skip_build
        else (("cmake",) if mode == "install" else ())
    )
    for tool in build_tools:
        if not shutil.which(tool):
            raise ValueError(f"Missing build tool: {tool}; see --print-deps")
    source = source_directory(
        args.source_dir,
        data_home / "mixxx-bpm-improvements/source",
        args.repository,
        args.ref,
    )
    prepare_sources(
        source,
        data_home / "mixxx-bpm-improvements/source",
        args.repository,
        args.ref,
        False if args.skip_build else args.update,
    )
    if args.skip_build:
        existing_build(args.build_dir, source)
        if mode == "install":
            validate_install_layout(args.build_dir, args.prefix)
    if mode == "install":
        check_launchers(args.prefix, args.bin_dir, data_home)
    if not args.skip_build:
        configure_build(source, args.build_dir, args.prefix, args.cmake_arg)
        run(build_command(args.build_dir, budget, jobs))
    if mode == "install":
        run(["cmake", "--install", args.build_dir, "--prefix", args.prefix])
    args.profile.mkdir(parents=True, exist_ok=True)
    if mode == "install":
        launcher = install_launchers(
            args.prefix, args.profile, args.bin_dir, data_home
        )
        print(
            f"\nInstalled. Start: {shlex.quote(str(launcher))}\n"
            "Desktop entry: Mixxx (BPM Improvements)"
        )
    else:
        command = [
            args.build_dir / "mixxx",
            "--resource-path",
            source / "res",
            "--settings-path",
            args.profile,
        ]
        print(
            "\nCompiled. Start in a terminal or use in your own shortcut:\n"
            + shlex.join([str(arg) for arg in command])
        )
    print(
        f"Profile: {args.profile}\n"
        "Existing profile settings are unchanged.\n"
        "Native analysis: Queen Mary and SoundTouch; new profiles use Auto.\n"
        "The managed source checkout is updated on normal runs.\n"
        "Developer checkouts require --update; --skip-build keeps sources."
    )


if __name__ == "__main__":
    try:
        main()
    except SourceUpdateError as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
    except (OSError, ValueError, subprocess.CalledProcessError) as error:
        print(
            f"Installation failed: {error}\n"
            "Run with --print-deps for prerequisites.",
            file=sys.stderr,
        )
        sys.exit(1)
    except KeyboardInterrupt:
        print(
            "Installation interrupted; rerun to resume the build.",
            file=sys.stderr,
        )
        sys.exit(130)
# End of autonomously generated text.
